<?php
$active_menu='notices';$active_submenu='manage_notices';include 'header.php';require_once __DIR__.'/../notices.php';oecrm_require_permission($conn,'notices','reports');$companyId=oecrm_current_company_id($conn);$id=(int)($_GET['id']??0);$s=mysqli_prepare($conn,'SELECT * FROM notices WHERE id=? AND company_id=?');mysqli_stmt_bind_param($s,'ii',$id,$companyId);mysqli_stmt_execute($s);$notice=mysqli_fetch_assoc(mysqli_stmt_get_result($s));mysqli_stmt_close($s);if(!$notice){http_response_code(404);exit('Notice not found.');}$employees=mysqli_query($conn,"SELECT e.employeeCode,e.name,e.designation,d.name department,r.first_seen_at,r.read_at,r.acknowledged_at FROM employeestbl e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN notice_receipts r ON r.employee_id=e.id AND r.notice_id=".(int)$id." WHERE e.company_id=".(int)$companyId." AND e.status=0 AND ('".mysqli_real_escape_string($conn,$notice['audience_type'])."'='all' OR ('".mysqli_real_escape_string($conn,$notice['audience_type'])."'='department' AND EXISTS(SELECT 1 FROM notice_targets t WHERE t.notice_id=".(int)$id." AND t.department_id=e.department_id)) OR ('".mysqli_real_escape_string($conn,$notice['audience_type'])."'='employee' AND EXISTS(SELECT 1 FROM notice_targets t WHERE t.notice_id=".(int)$id." AND t.employee_id=e.id))) ORDER BY e.name");$events=mysqli_query($conn,'SELECT * FROM notice_events WHERE notice_id='.(int)$id.' ORDER BY id DESC LIMIT 200');
?><div id="page-wrapper" class="compact-admin-page notice-admin-page"><div class="panel panel-default"><div class="panel-heading foundation-heading"><span><?php echo oecrm_h($notice['title']);?></span><small>Delivery and acknowledgement report</small></div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Employee</th><th>Department</th><th>First Seen</th><th>Read</th><th>Acknowledged</th></tr></thead><tbody><?php while($e=mysqli_fetch_assoc($employees)):?><tr><td><strong><?php echo oecrm_h($e['name']);?></strong><small><?php echo oecrm_h($e['employeeCode'].' - '.$e['designation']);?></small></td><td><?php echo oecrm_h($e['department']?:'Unassigned');?></td><td><?php echo oecrm_h($e['first_seen_at']?:'Not seen');?></td><td><?php echo oecrm_h($e['read_at']?:'Unread');?></td><td><?php echo oecrm_h($e['acknowledged_at']?:'Pending');?></td></tr><?php endwhile;?></tbody></table></div></div><div class="panel panel-default"><div class="panel-heading">Activity History</div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Date</th><th>Actor</th><th>Event</th><th>Details</th><th>IP</th></tr></thead><tbody><?php while($ev=mysqli_fetch_assoc($events)):?><tr><td><?php echo oecrm_h($ev['created_at']);?></td><td><?php echo oecrm_h(ucfirst($ev['actor_type']).' #'.$ev['actor_id']);?></td><td><?php echo oecrm_h(ucwords(str_replace('_',' ',$ev['event_type'])));?></td><td><?php echo oecrm_h($ev['details']);?></td><td><?php echo oecrm_h($ev['ip_address']);?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include 'footer.php';?>
